#!/usr/bin/env bash
# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# Build the patient's side for the browser:
#   1. Niobium's OpenFHE fork -> static WebAssembly libraries (once; minutes)
#   2. wasm/risk_client_wasm.cpp + common.hpp -> static/risk_client.{js,wasm}
#
# The OpenFHE flags mirror the native build in the repo Makefile
# (config-openfhe-release): WITH_CPROBES=ON, WITH_REDUCED_NOISE=ON, no OpenMP,
# MATHBACKEND 4, 64-bit native integers, so both sides serialize identically.
#
# Needs Emscripten (`brew install emscripten`).
set -euo pipefail

WEB="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$WEB/../../.." && pwd)"
OFHE_SRC="$REPO/vendor/niobium-fhetch/vendor/openfhe"
B="$WEB/build"; INST="$B/install"

if [ ! -f "$INST/lib/libOPENFHEpke_static.a" ]; then
  emcmake cmake -S "$OFHE_SRC" -B "$B/openfhe" \
    -DCMAKE_BUILD_TYPE=Release -DBUILD_STATIC=ON -DBUILD_SHARED=OFF \
    -DBUILD_UNITTESTS=OFF -DBUILD_EXAMPLES=OFF -DBUILD_BENCHMARKS=OFF -DBUILD_EXTRAS=OFF \
    -DWITH_CPROBES=ON -DWITH_REDUCED_NOISE=ON -DWITH_OPENMP=OFF -DWITH_NATIVEOPT=OFF \
    -DGIT_SUBMOD_AUTO=OFF -DCMAKE_INSTALL_PREFIX="$INST"
  emmake make -C "$B/openfhe" -j8
  emmake make -C "$B/openfhe" install
fi

I="$INST/include/openfhe"
mkdir -p "$WEB/static"
em++ -O3 -std=c++17 -fexceptions -DOPENFHE_CPROBES -DMATHBACKEND=4 \
  -Wno-unused-but-set-variable -Wno-unknown-pragmas \
  -I"$I" -I"$I/core" -I"$I/pke" -I"$I/binfhe" -I"$I/cereal" \
  "$WEB/wasm/risk_client_wasm.cpp" "$WEB/wasm/probe_stubs.cpp" \
  "$INST/lib/libOPENFHEpke_static.a" "$INST/lib/libOPENFHEbinfhe_static.a" \
  "$INST/lib/libOPENFHEcore_static.a" \
  -lembind -fexceptions \
  -sMODULARIZE=1 -sEXPORT_ES6=1 -sEXPORT_NAME=createRiskClient \
  -sENVIRONMENT=web,worker,node -sDYNAMIC_EXECUTION=0 \
  -sALLOW_MEMORY_GROWTH=1 -sINITIAL_MEMORY=256MB -sMAXIMUM_MEMORY=4GB -sSTACK_SIZE=8MB \
  -o "$WEB/static/risk_client.js"
ls -l "$WEB/static/risk_client.js" "$WEB/static/risk_client.wasm"
